import { StockFilter } from "./types";
import { getStockUniverse as getFMPStockUniverse, getLastFMPError } from "./fmpService";

// S&P 500 representative stock data with fundamental metrics
// Now sourced from Financial Modeling Prep API with daily caching
export interface StockData {
  ticker: string;
  name: string;
  sector: number; // 1=tech, 2=healthcare, 3=finance, 4=energy, 5=consumer, etc.

  // Valuation metrics
  pe_ratio: number;
  forward_pe: number;
  price_to_book: number;

  // Dividend metrics
  dividend_yield: number;
  dividend_growth_years: number;
  payout_ratio: number;

  // Growth metrics
  revenue_growth: number;
  revenue_growth_quarters: number;
  net_income_growth_quarters?: number;
  earnings_growth: number;

  // Profitability metrics
  profit_margin: number;
  roe: number;
  roic: number;

  // Leverage & liquidity
  debt_to_equity: number;
  current_ratio: number;
  free_cash_flow_per_share: number;

  // Per-share metrics
  revenue_per_share: number;
  net_income_per_share: number;

  // Market metrics
  market_cap: number; // in billions
  beta: number;
  week52_high_pct: number;

  // Share metrics
  shares_outstanding: number;
  shares_change_pct: number;

  // Other
  ipo_date?: string;

  // Historical annual returns for backtesting (approximate)
  historical_returns: {
    [year: string]: number; // annual return as decimal
  };
}

export interface StockDatabaseResult {
  stocks: StockData[];
  dataSource: "fmp" | "hardcoded";
  stockCount: number;
  error?: string; // Error message when FMP fails and fallback is used
}

/**
 * Gets the stock database from FMP API (cached daily) with fallback to hardcoded data
 */
export async function getStockDatabase(): Promise<StockDatabaseResult> {
  try {
    // Try to get fresh data from FMP (will use cache if available)
    const fmpStocks = await getFMPStockUniverse();
    if (fmpStocks && fmpStocks.length > 0) {
      console.log(`[StockData] Using FMP data: ${fmpStocks.length} stocks`);
      return { stocks: fmpStocks, dataSource: "fmp", stockCount: fmpStocks.length };
    }
  } catch (error) {
    console.warn('[StockData] Failed to load FMP data, using fallback:', error);
  }

  // Get the detailed error from FMP service
  const fmpError = getLastFMPError();
  const errorMessage = fmpError || "FMP API returned no data. Using hardcoded fallback instead.";

  // Fallback to hardcoded data
  console.log(`[StockData] Using hardcoded fallback: ${STOCK_DATABASE.length} stocks`);
  return {
    stocks: STOCK_DATABASE,
    dataSource: "hardcoded",
    stockCount: STOCK_DATABASE.length,
    error: errorMessage
  };
}

